     ]:
         from sglang.srt.arg_groups.deepseek_v4_hook import (
             validate_deepseek_v4_cp,
+            validate_deepseek_v4_swa_recompute,
             validate_deepseek_v41_features,
         )

         # Before the CP validation: V4.1 rejects CP outright, the actionable message.
         validate_deepseek_v41_features(server_args)
+        validate_deepseek_v4_swa_recompute(server_args)
         validate_deepseek_v4_cp(server_args)

         if get_platform().is_sm120:

@@ -266,6 +266,9 @@ def process_batch_result_prefill(
         if self.is_generation:
             if result.copy_done is not None:
                 result.copy_done.synchronize()
+            for req in batch.reqs:
+                if req.swa_recompute is not None:
+                    self.tree_cache.release_swa_recompute_workspace(req)
             auxiliary_output_starts = self.snapshot_auxiliary_output_starts(
                 batch, result
             )

